method Strongest_Extension(class_name: string, extensions: seq<string>) returns (result: string)
    requires class_name != ""
    requires extensions != []
    requires forall e: string :: e in extensions ==> e != ""
    ensures result == class_name + "." + strongest_extension_name
    ensures strongest_extension_name in extensions
    ensures forall e: string :: e in extensions && e != strongest_extension_name ==> 
            (strength(e) < strength(strongest_extension_name) || 
             (strength(e) == strength(strongest_extension_name) && e != strongest_extension_name))
{
    var strongest_extension_name := extensions[0];
    var strongest_strength := strength(strongest_extension_name);

    var i := 1;
    while i < |extensions|
        invariant 0 <= i <= |extensions|
        invariant strongest_extension_name in extensions
        invariant forall j: int :: 0 <= j < i ==> extensions[j] != ""
        invariant forall j: int :: 0 <= j < i ==> 
                    (strength(extensions[j]) < strongest_strength || 
                     (strength(extensions[j]) == strongest_strength && extensions[j] != strongest_extension_name))
    {
        if strength(extensions[i]) > strongest_strength {
            strongest_extension_name := extensions[i];
            strongest_strength := strength(strongest_extension_name);
        }
        i := i + 1;
    }

    result := class_name + "." + strongest_extension_name;
}

function method strength(ext: string): int
    requires ext != ""
    ensures result == count_uppercase(ext) - count_lowercase(ext)
{
    var count_uppercase := 0;
    var count_lowercase := 0;

    var i := 0;
    while i < |ext|
        invariant 0 <= i <= |ext|
        invariant count_uppercase >= 0 && count_lowercase >= 0
    {
        if ext[i] >= 'A' && ext[i] <= 'Z' {
            count_uppercase := count_uppercase + 1;
        } else if ext[i] >= 'a' && ext[i] <= 'z' {
            count_lowercase := count_lowercase + 1;
        }
        i := i + 1;
    }

    return count_uppercase - count_lowercase;
}
